-- تحديث أسئلة كيمياء 2-2 التي عُدّلت بعد الرفع (21 سؤالًا في 4 هدفًا). مولّد آليًا بـ scripts/build-chem22-patch.js — لا تعدّله يدويًا.
-- لا يغيّر حالة الاعتماد. آمن للتكرار. إن لم تكن نفّذت ملفات seed-chem22 بعد فلا حاجة إليه (ملفات seed محدّثة).
begin;
update public.questions set stem = 'يمثل المخطط الآتي المحتوى الحراري لتفاعل ما. ما نوع التفاعل؟', images = '[{"src":"qimg/chem22/c1-endo-233.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات في الأسفل ومستوى النواتج في الأعلى، وسهم إلى أعلى مكتوب عليه ΔH = +233 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O04') and type = 'mcq' and number = 4);
update public.questions set stem = 'ماذا يمثل المحور الرأسي (؟) في مخطط المحتوى الحراري الآتي؟', images = '[{"src":"qimg/chem22/c1-axis-q.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات أعلى من مستوى النواتج وسهم ΔH إلى أسفل، والمحور الرأسي عليه علامة استفهام"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 1);
update public.questions set stem = 'يمثل المخطط الآتي المحتوى الحراري لتفاعل الكمادة الساخنة. ماذا يدل اتجاه السهم إلى أسفل؟', images = '[{"src":"qimg/chem22/c1-hot-pack.svg","alt":"مخطط المحتوى الحراري للكمادة الساخنة: مستوى 4Fe(s) + 3O₂(g) أعلى من مستوى 2Fe₂O₃(s)، وسهم إلى أسفل ΔH = −1625 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 2);
update public.questions set stem = 'اعتمادًا على مخطط المحتوى الحراري الآتي، ما نوع التفاعل؟ وكيف عرفت ذلك؟', images = '[{"src":"qimg/chem22/c1-endo-233.svg","alt":"مخطط محتوى حراري: مستوى المتفاعلات في الأسفل ومستوى النواتج في الأعلى، وسهم إلى أعلى مكتوب عليه ΔH = +233 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 3);
update public.questions set stem = 'اعتمادًا على مخطط المحتوى الحراري للماء الآتي، ما قيمة ΔH للتحول H₂O(l) → H₂O(s)؟', images = '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 5);
update public.questions set stem = 'اعتمادًا على مخطط المحتوى الحراري للماء الآتي، ما الطاقة اللازمة لتحويل 1 mol من H₂O(s) إلى H₂O(g)؟', images = '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 6);
update public.questions set stem = 'يمثل الشكل الآتي مخططي المحتوى الحراري لتفاعلين (س) و(ص). أيّ العبارات الآتية صحيحة؟', images = '[{"src":"qimg/chem22/c1-two-diagrams.svg","alt":"مخططا محتوى حراري: في (س) سهم إلى أسفل مقداره 90 kJ من المتفاعلات إلى النواتج، وفي (ص) سهم إلى أعلى مقداره 30 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'mcq' and number = 7);
update public.questions set stem = 'يمثل المخطط الآتي المحتوى الحراري لتفاعل الكمادة الساخنة (الحرارة تنطلق من النظام إلى المحيط). فسّر هذا المخطط مبينًا: نوع التفاعل، ودلالة موقعي المستويين، ودلالة اتجاه السهم، وإشارة ΔH.', images = '[{"src":"qimg/chem22/c1-hot-pack.svg","alt":"مخطط المحتوى الحراري للكمادة الساخنة: مستوى 4Fe(s) + 3O₂(g) أعلى من مستوى 2Fe₂O₃(s)، وسهم إلى أسفل ΔH = −1625 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'essay' and number = 1);
update public.questions set images = '[{"src":"qimg/chem22/c1-water-levels.svg","alt":"مستويات المحتوى الحراري للماء: H₂O(s) في الأسفل ثم H₂O(l) أعلى منه بمقدار 6.01 kJ ثم H₂O(g) أعلى بمقدار 40.7 kJ"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L2-O10') and type = 'essay' and number = 3);
update public.questions set stem = 'يمثل المنحنى الآتي تسخين عينة من الجليد عند −20 °C بمعدل ثابت حتى تحولت إلى بخار عند 120 °C. ما الذي يحدث للعينة في الجزء (2)؟', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'mcq' and number = 1);
update public.questions set stem = 'في الجزء (4) من منحنى تسخين الماء الآتي (الغليان عند 100 °C)، كيف تتغير طاقة الحركة وطاقة الوضع لجزيئات الماء؟', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'mcq' and number = 2);
update public.questions set stem = 'في منحنى تسخين الماء الآتي بمعدل ثابت، يكون الجزء (4) عند 100 °C أطول كثيرًا من الجزء (2) عند 0 °C. ما سبب ذلك؟', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'mcq' and number = 4);
update public.questions set stem = 'في منحنى تسخين الماء الآتي بمعدل ثابت، يكون ميل الجزء (5) (تسخين بخار الماء) أكبر من ميل الجزء (3) (تسخين الماء السائل). ما تفسير ذلك؟ (C للسائل = 4.184 J/g·°C، C للبخار = 2.01 J/g·°C)', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'mcq' and number = 5);
update public.questions set stem = 'ما كمية الحرارة التي تمتصها عينة كتلتها 90.0 g من الماء في الجزء (3) من منحنى التسخين الآتي، حيث ترتفع درجة حرارتها من 0 °C إلى 100 °C؟ (C للماء السائل = 4.184 J/g·°C، C للجليد = 2.03 J/g·°C)', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'mcq' and number = 6);
update public.questions set stem = 'يمثل المنحنى الآتي تسخين عينة من الجليد عند −20 °C بمعدل ثابت حتى أصبحت بخارًا عند 120 °C. حدّد ماذا يحدث للماء في كل جزء من الأجزاء الخمسة المرقمة، وبيّن أين تُستهلك الحرارة الممتصة: في زيادة طاقة الحركة أم طاقة الوضع.', images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'essay' and number = 1);
update public.questions set images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'essay' and number = 2);
update public.questions set images = '[{"src":"qimg/chem22/c1-heating-curve.svg","alt":"منحنى تسخين الماء من −20 °C إلى 120 °C بمعدل ثابت، بخمسة أجزاء مرقمة: 1 مائل حتى 0 °C، 2 أفقي عند 0 °C، 3 مائل حتى 100 °C، 4 أفقي عند 100 °C، 5 مائل فوق 100 °C"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L3-O08') and type = 'essay' and number = 3);
update public.questions set stem = 'في تدريج حرارة التكوين القياسية الآتي يُرسم سهم ΔH°f لكل مركب من خط العناصر (الصفر) إلى مستوى المركب. علامَ يدل اتجاه السهم؟', images = '[{"src":"qimg/chem22/c1-formation-no2-so3.svg","alt":"تدريج حرارة التكوين القياسية: خط الصفر للعناصر في حالاتها القياسية، وNO₂(g) فوقه عند +33.2 kJ/mol بسهم صاعد، وSO₃(g) تحته عند −396 kJ/mol بسهم هابط"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L4-O08') and type = 'mcq' and number = 2);
update public.questions set stem = 'اعتمادًا على تدريج حرارة التكوين القياسية الآتي، ما قيمة ΔH للتحول H₂O(l) → H₂O(g) عند 298 K التي تمثلها المسافة بين مستويي الماء؟', images = '[{"src":"qimg/chem22/c1-formation-water.svg","alt":"تدريج حرارة التكوين: خط الصفر H₂(g) + ½O₂(g)، وH₂O(g) عند −241.8 kJ/mol، وH₂O(l) عند −285.8 kJ/mol"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L4-O08') and type = 'mcq' and number = 5);
update public.questions set stem = 'في تدريج حرارة التكوين القياسية الآتي، أين يقع تقريبًا H₂O(l) الذي ΔH°f له −286 kJ/mol؟', images = '[{"src":"qimg/chem22/c1-formation-no2-so3.svg","alt":"تدريج حرارة التكوين القياسية: خط الصفر للعناصر في حالاتها القياسية، وNO₂(g) فوقه عند +33.2 kJ/mol بسهم صاعد، وSO₃(g) تحته عند −396 kJ/mol بسهم هابط"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L4-O08') and type = 'mcq' and number = 7);
update public.questions set stem = 'يمثل الشكل الآتي تدريج حرارة التكوين القياسية للمركبين NO₂(g) وSO₃(g) (العناصر N₂(g) وO₂(g) وS(s) عند 0.0 kJ/mol). فسّر ما يدل عليه موقع كل من NO₂ وSO₃ بالنسبة إلى خط الصفر من حيث نوع تفاعل التكوين (ماصّ أم طارد)، ثم قارن استقرار كل منهما بعناصره.', images = '[{"src":"qimg/chem22/c1-formation-no2-so3.svg","alt":"تدريج حرارة التكوين القياسية: خط الصفر للعناصر في حالاتها القياسية، وNO₂(g) فوقه عند +33.2 kJ/mol بسهم صاعد، وSO₃(g) تحته عند −396 kJ/mol بسهم هابط"}]'::jsonb, updated_at = now() where id = (select id from public.questions where objective_id = (select id from public.objectives where code = 'K22-C1-L4-O08') and type = 'essay' and number = 1);
commit;
